// Extract Payload v5.8 — NO $env
const raw = $input.first().json.body || $input.first().json;

let persona = {};
try {
  const p = raw.persona;
  persona = typeof p === 'string' ? JSON.parse(p) : (p || {});
} catch(e) { persona = {}; }

const userId = raw.userId || persona.userId || '';
persona.userId = userId;
persona.language_preference = persona.language_preference || 'th';
persona.tokens = persona.tokens || {};
persona.relevant_memories = persona.relevant_memories || [];
persona.key_facts = persona.key_facts || [];
persona.interests = persona.interests || [];
persona.ethical_profile = persona.ethical_profile || null;

console.log(`[WF2 Extract v5.8] userId=${userId.substring(0,8)}... | lang=${persona.language_preference} | memories=${persona.relevant_memories.length} | hasToken=${!!persona.tokens?.openrouter_access_token}`);

return {
  json: {
    userId,
    sessionId:       raw.sessionId,
    source:          raw.source || 'chat',
    message:         raw.message || '',
    originalMessage: raw.originalMessage || raw.message || '',
    timestamp:       raw.timestamp || new Date().toISOString(),
    replyTarget:     raw.replyTarget,
    replyToken:      raw.replyToken,
    databaseUrl:     raw.databaseUrl || '',
    persona,
    rawPayload:      raw
  }
};

// JARVIS Router v5.8 — NO $env AT ALL
// ใช้ token จาก persona.tokens เท่านั้น
// $helpers.httpRequest() — n8n built-in, ไม่ถูก sandbox block
// ─────────────────────────────────────────────────────────────
const payload  = $input.first().json;
const message  = payload.message || '';
const persona  = payload.persona || {};
const lang     = persona.language_preference || 'th';
const userName = persona.name || 'User';
const tier     = persona.subscriptionTier || 'FREE';
const stage    = persona.ethical_profile?.growth_stage || 2;
const stageLabel = persona.ethical_profile?.growth_stage_label || 'Developing';
const interests  = (persona.interests || []).slice(0, 5).join(', ') || 'not specified';
const keyFacts   = (persona.key_facts || []).slice(0, 3).join(' | ') || 'none';
const recentMemTypes = (persona.relevant_memories || []).map(m => m.type).join(', ') || 'none';

// ── API Key — จาก persona.tokens เท่านั้น (NO $env) ──────────
const apiKey  = persona.tokens?.openrouter_access_token || '';
const keyType = apiKey ? 'user' : 'none';

const PAID_MODEL = 'anthropic/claude-haiku-4-5';
const FREE_MODEL = 'meta-llama/llama-3.3-70b-instruct:free';
const model = apiKey ? PAID_MODEL : FREE_MODEL;

// ── n8n base URL — hardcode จาก webhookUrl ────────────────────
// ดึง base URL จาก WF2 Entry webhook URL (ไม่ต้องใช้ $env)
const n8nBase = 'http://localhost:5678';
const AGENT_URLS = {
  wf3a: `${n8nBase}/webhook/wf3a-secretary`,
  wf3b: `${n8nBase}/webhook/wf3b-soul`,
  wf3c: `${n8nBase}/webhook/wf3c-careercoach`,
  wf3d: `${n8nBase}/webhook/wf3d-explorer`,
  wf3e: `${n8nBase}/webhook/wf3e-creator`,
  wf3f: `${n8nBase}/webhook/wf3f-homemate`,
  wf3g: `${n8nBase}/webhook/wf3g-healthcoach`
};

// ── System Prompt ─────────────────────────────────────────────
const SYSTEM_PROMPT = `You are JARVIS — the central cognitive router of an advanced personal AI system.
Your function: Decompose the user's message into a structured dispatch plan.

AGENT REGISTRY:
wf3a [SECRETARY] — Calendar, reminders, email, LINE notify, Telegram, Discord, tasks, social media
wf3b [SOUL] — Emotions, journaling, personal growth, habits, relationships, crisis (hopelessness/self-harm → always wf3b + crisis=true)
wf3c [CAREER COACH] — Finance, budget, investment, stocks, career, resume, interview
wf3d [EXPLORER] — Web search, news, weather, exchange rates, maps, research
wf3e [CREATOR] — AI image, TTS, creative writing, translation
wf3f [HOME MATE] — Music (Spotify/Sonos), smart home (Home Assistant)
wf3g [HEALTH COACH] — Nutrition, calorie, workout, exercise, health tracking

RULES:
- Single intent → 1 item; Multi → max 3, ordered by priority
- crisis → wf3b, crisis=true always
- Output ONLY valid JSON, no markdown:
{"intents":[{"agent":"wf3x","priority":1,"sub_task":"instruction","gating":false,"crisis":false}]}

CONTEXT: User=${userName} | Lang=${lang} | Tier=${tier} | Growth=${stage}/5 (${stageLabel})
Interests: ${interests} | Key facts: ${keyFacts} | Recent memories: ${recentMemTypes}`;

// ── Keyword Fallback ──────────────────────────────────────────
function keywordRoute(msg) {
  const t = msg.toLowerCase();
  if (/อยากตาย|ฆ่าตัว|สิ้นหวัง|want to die|hopeless/.test(t))
    return { agent: 'wf3b', priority: 1, sub_task: msg, gating: true, crisis: true };
  if (/นัด|ปฏิทิน|เตือน|ส่ง email|ส่งเมล|แจ้งเตือน/.test(t))
    return { agent: 'wf3a', priority: 1, sub_task: msg, gating: false, crisis: false };
  if (/หุ้น|กองทุน|งบ|เงิน|ลงทุน|resume|สัมภาษณ์/.test(t))
    return { agent: 'wf3c', priority: 1, sub_task: msg, gating: false, crisis: false };
  if (/ค้นหา|ข่าว|สภาพอากาศ|แผนที่|search|weather/.test(t))
    return { agent: 'wf3d', priority: 1, sub_task: msg, gating: false, crisis: false };
  if (/รูปภาพ|สร้างรูป|แปล|image|translate|tts/.test(t))
    return { agent: 'wf3e', priority: 1, sub_task: msg, gating: false, crisis: false };
  if (/เพลง|spotify|music|บ้าน|home/.test(t))
    return { agent: 'wf3f', priority: 1, sub_task: msg, gating: false, crisis: false };
  if (/อาหาร|แคล|ออกกำลัง|สุขภาพ|nutrition|workout/.test(t))
    return { agent: 'wf3g', priority: 1, sub_task: msg, gating: false, crisis: false };
  // default → wf3b (soul) สำหรับ general conversation
  return { agent: 'wf3b', priority: 1, sub_task: msg, gating: false, crisis: false };
}

function parseIntents(text) {
  const VALID = ['wf3a','wf3b','wf3c','wf3d','wf3e','wf3f','wf3g'];
  try {
    const clean = (text || '').replace(/```json|```/g, '').trim();
    const parsed = JSON.parse(clean);
    const arr = Array.isArray(parsed.intents) ? parsed.intents : [parsed];
    const valid = arr
      .filter(i => i && VALID.includes(i.agent))
      .map(i => ({
        agent:    i.agent,
        priority: [1,2,3].includes(i.priority) ? i.priority : 1,
        sub_task: i.sub_task || message,
        gating:   i.gating === true,
        crisis:   i.crisis === true
      }))
      .sort((a, b) => a.priority - b.priority);
    const seen = new Set();
    const deduped = valid.filter(i => !seen.has(i.agent) && seen.add(i.agent));
    if (deduped.length === 0) throw new Error('empty');
    return deduped;
  } catch(_) {
    return [keywordRoute(message)];
  }
}

// ── Call OpenRouter via $helpers.httpRequest (NO fetch, NO $env) ─
let rawText    = null;
let usedModel  = null;
let routerError = null;

if (apiKey) {
  try {
    const responseData = await $helpers.httpRequest({
      method:  'POST',
      url:     'https://openrouter.ai/api/v1/chat/completions',
      headers: {
        'Authorization': `Bearer ${apiKey}`,
        'Content-Type':  'application/json',
        'HTTP-Referer':  'https://7on.ai'
      },
      body: JSON.stringify({
        model,
        max_tokens: 300,
        temperature: 0,
        response_format: { type: 'json_object' },
        messages: [
          { role: 'system', content: SYSTEM_PROMPT },
          { role: 'user',   content: message }
        ]
      })
    });
    const data = typeof responseData === 'string' ? JSON.parse(responseData) : responseData;
    rawText   = data?.choices?.[0]?.message?.content || null;
    usedModel = model;
    console.log(`[JARVIS v5.8] ✅ OpenRouter ok | model=${model} | keyType=${keyType}`);
  } catch (err) {
    routerError = err.message || String(err);
    console.warn(`[JARVIS v5.8] ⚠️ OpenRouter failed: ${routerError} — keyword fallback`);
  }
} else {
  console.log('[JARVIS v5.8] No API key — keyword fallback');
}

// ── Parse & dispatch ──────────────────────────────────────────
const intents  = parseIntents(rawText);
const intent   = intents[0];
const hasCrisis = intents.some(i => i.crisis);
const hasGating = intents.some(i => i.gating || i.crisis);

console.log(`[JARVIS v5.8] → ${intent.agent} | crisis=${hasCrisis} | model=${usedModel || 'keyword'}`);

return {
  json: {
    userId:           payload.userId,
    sessionId:        payload.sessionId,
    source:           payload.source,
    message:          intent.sub_task,
    originalMessage:  message,
    databaseUrl:      payload.databaseUrl,
    replyTarget:      payload.replyTarget,
    replyToken:       payload.replyToken,
    timestamp:        payload.timestamp,
    persona:          payload.persona,
    targetAgent:      intent.agent,
    targetUrl:        AGENT_URLS[intent.agent],
    needsGating:      intent.gating,
    hasCrisis,
    _intents:         intents,
    _dispatch_mode:   'single',
    _router_model:    usedModel,
    _router_key_type: keyType,
    _router_version:  'v5.8',
    _gating_intents:  hasGating ? intents.filter(i => i.gating || i.crisis) : [],
    _router_error:    routerError
  }
};

// Format Response v5.8
const raw = $input.first().json;

const isError = raw.errorMessage || raw.error || raw.httpCode;
if (isError) {
  const errMsg = raw.errorMessage || raw.error || 'Service error';
  console.warn(`[Format Response v5.8] WF3x error: ${errMsg}`);
  return {
    json: {
      message:        'ขออภัยครับ ระบบขัดข้องชั่วคราว กรุณาลองใหม่อีกครั้ง',
      response:       'ขออภัยครับ ระบบขัดข้องชั่วคราว กรุณาลองใหม่อีกครั้ง',
      output:         'ขออภัยครับ ระบบขัดข้องชั่วคราว กรุณาลองใหม่อีกครั้ง',
      userId:         raw.userId,
      sessionId:      raw.sessionId,
      _error:         errMsg,
      _router_version:'v5.8'
    }
  };
}

const msg = raw.message || raw.response || raw.output || raw.agentOutput || raw.text
            || 'ขออภัย ไม่สามารถตอบได้ในขณะนี้ครับ';

console.log(`[Format Response v5.8] agent=${raw._primary_agent || raw.targetAgent} | len=${String(msg).length}`);

return {
  json: {
    message:        msg,
    response:       msg,
    output:         msg,
    userId:         raw.userId,
    sessionId:      raw.sessionId,
    _primary_agent: raw._primary_agent || raw.targetAgent,
    _router_model:  raw._router_model,
    _router_version:'v5.8',
    hasCrisis:      raw.hasCrisis || false
  }
};
